arguments.command:
# Fix the ingress with correct host and tls secret reference
kubectl patch ingress argocd-server -n argocd --type=json \
  -p='[
    {"op":"replace","path":"/spec/rules/0/host","value":"argocd.feralfantasies.co.uk"},
    {"op":"add","path":"/spec/tls","value":[{"hosts":["argocd.feralfantasies.co.uk"],"secretName":"argocd-tls-secret"}]}
  ]' 2>&1 && sleep 5 && curl -sS --max-time 10 https://argocd.feralfantasies.co.uk/ 2>&1 | head -3
